#!/usr/bin/env python3
"""A small persistent, dependency-free HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import logging
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024
LOG = logging.getLogger("http-kv")


class Store:
    def __init__(self, path: str):
        self.path = os.path.abspath(path)
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, object]] = {}
        self._load()

    def _load(self) -> None:
        try:
            with open(self.path, "r", encoding="utf-8") as stream:
                raw = json.load(stream)
            if not isinstance(raw, dict):
                raise ValueError("state is not an object")
            now = time.time()
            for key, entry in raw.items():
                if (isinstance(key, str) and isinstance(entry, dict)
                        and "value" in entry
                        and (entry.get("expires_at") is None
                             or (isinstance(entry.get("expires_at"), (int, float))
                                 and not isinstance(entry.get("expires_at"), bool)))):
                    expiry = entry.get("expires_at")
                    if expiry is None or expiry > now:
                        self.entries[key] = {"value": entry["value"], "expires_at": expiry}
        except FileNotFoundError:
            return
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            LOG.warning("could not load state file %s: %s; starting empty", self.path, exc)

    def _write_locked(self) -> None:
        directory = os.path.dirname(self.path) or "."
        basename = os.path.basename(self.path)
        fd, temporary = tempfile.mkstemp(prefix=f".{basename}.", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(self.entries, stream, ensure_ascii=False, separators=(",", ":"),
                          allow_nan=False)
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, self.path)
        except Exception:
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise

    def _remove_expired_locked(self, now: float) -> bool:
        expired = [key for key, entry in self.entries.items()
                   if entry["expires_at"] is not None and entry["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def put(self, key: str, value: object, ttl: float | int | None) -> tuple[bool, None]:
        with self.lock:
            self._remove_expired_locked(time.time())
            created = key not in self.entries
            expiry = None if ttl is None else time.time() + float(ttl)
            self.entries[key] = {"value": value, "expires_at": expiry}
            self._write_locked()
            return created, None

    def get(self, key: str) -> object | None:
        with self.lock:
            changed = self._remove_expired_locked(time.time())
            if changed:
                self._write_locked()
            entry = self.entries.get(key)
            return None if entry is None else entry["value"]

    def delete(self, key: str) -> bool:
        with self.lock:
            self._remove_expired_locked(time.time())
            if key not in self.entries:
                return False
            del self.entries[key]
            self._write_locked()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            changed = self._remove_expired_locked(time.time())
            if changed:
                self._write_locked()
            return sorted(self.entries)


class Handler(BaseHTTPRequestHandler):
    server_version = "PersistentKV/1.0"

    @property
    def store(self) -> Store:
        return self.server.store  # type: ignore[attr-defined]

    def log_message(self, format: str, *args: object) -> None:
        LOG.info("%s - %s", self.address_string(), format % args)

    def _send_json(self, status: int, payload: object, *, head_only: bool = False) -> None:
        data = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if not head_only:
            self.wfile.write(data)

    def _error(self, status: int, message: str, *, allow: str | None = None) -> None:
        if allow:
            self.send_response(status)
            self.send_header("Allow", allow)
            data = json.dumps({"error": message}, separators=(",", ":")).encode()
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        else:
            self._send_json(status, {"error": message})

    def _key(self, path: str) -> str | None:
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix):]
        if not encoded or "/" in encoded:
            return None
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError:
            return None
        return key if key else None

    def _read_body(self) -> bytes | None:
        header = self.headers.get("Content-Length")
        try:
            length = int(header) if header is not None else -1
        except ValueError:
            length = -1
        if length < 0:
            self._error(400, "Content-Length is required")
            return None
        if length > MAX_BODY:
            self._error(413, "request body too large")
            return None
        return self.rfile.read(length)

    def do_PUT(self) -> None:
        path = urlsplit(self.path).path
        key = self._key(path)
        if key is None:
            self._error(400 if path.startswith("/v1/kv/") else 404, "invalid key or route")
            return
        body = self._read_body()
        if body is None:
            return
        try:
            parsed = json.loads(body.decode("utf-8"), parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
            self._error(400, "malformed JSON")
            return
        if not isinstance(parsed, dict) or "value" not in parsed or set(parsed) - {"value", "ttl_seconds"}:
            self._error(400, "body must contain value and optional ttl_seconds")
            return
        ttl = parsed.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                                or not math.isfinite(float(ttl)) or float(ttl) <= 0):
            self._error(400, "ttl_seconds must be finite and greater than zero")
            return
        try:
            created, _ = self.store.put(key, parsed["value"], ttl)
        except (OSError, TypeError, ValueError) as exc:
            LOG.error("persisting PUT failed: %s", exc)
            self._error(500, "could not persist value")
            return
        self._send_json(201 if created else 200, {"key": key, "value": parsed["value"]})

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path == "/health":
            self._send_json(200, {"status": "ok"})
        elif path == "/v1/keys":
            try:
                self._send_json(200, {"keys": self.store.keys()})
            except (OSError, TypeError, ValueError):
                self._error(500, "could not persist expired entries")
        elif path.startswith("/v1/kv/"):
            key = self._key(path)
            if key is None:
                self._error(400, "invalid key")
                return
            try:
                value = self.store.get(key)
            except (OSError, TypeError, ValueError):
                self._error(500, "could not persist expired entries")
                return
            if value is None and not self.store.contains(key):
                self._error(404, "key not found")
            else:
                self._send_json(200, {"key": key, "value": value})
        else:
            self._error(404, "unknown route")

    def do_DELETE(self) -> None:
        path = urlsplit(self.path).path
        key = self._key(path)
        if key is None:
            self._error(400 if path.startswith("/v1/kv/") else 404, "invalid key or route")
            return
        try:
            present = self.store.delete(key)
        except (OSError, TypeError, ValueError):
            self._error(500, "could not persist deletion")
            return
        if present:
            self.send_response(204)
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            self._error(404, "key not found")

    def do_POST(self) -> None:
        self._error(405, "method not allowed", allow="GET, PUT, DELETE")

    do_PATCH = do_POST
    do_OPTIONS = do_POST


def _contains(self: Store, key: str) -> bool:
    with self.lock:
        return key in self.entries


Store.contains = _contains  # type: ignore[attr-defined]


def main() -> None:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", required=True)
    args = parser.parse_args()
    logging.basicConfig(stream=sys.stderr, level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    store = Store(args.data)
    server = ThreadingHTTPServer((args.host, args.port), Handler)
    server.store = store  # type: ignore[attr-defined]

    def stop(_signum: int, _frame: object) -> None:
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

